import Chord from '../chord';
import ChordLyricsPair from '../chord_sheet/chord_lyrics_pair';
import Comment from '../chord_sheet/comment';
import Evaluatable from '../chord_sheet/chord_pro/evaluatable';
import Formatter from './formatter';
import Item from '../chord_sheet/item';
import Key from '../key';
import Line from '../chord_sheet/line';
import Literal from '../chord_sheet/chord_pro/literal';
import Metadata from '../chord_sheet/metadata';
import SoftLineBreak from '../chord_sheet/soft_line_break';
import Song from '../chord_sheet/song';
import Tag from '../chord_sheet/tag';
import Ternary from '../chord_sheet/chord_pro/ternary';
import parseMetaValue from '../chord_sheet/chord_pro/parse_meta_value';

import { CHORD_STYLE } from '../chord_sheet/tags';
import { getBaseDefaultConfig } from './configuration/default_config_manager';
import {
  ChordProFormatterConfiguration,
  chordProSpecificDefaults,
} from './configuration/chord_pro_configuration';
import {
  NUMBER, NUMERAL, NullableChordStyle, SOLFEGE, SYMBOL,
} from '../constants';

/**
 * Formats a song into a ChordPro chord sheet
 */
class ChordProFormatter extends Formatter<ChordProFormatterConfiguration> {
  protected getDefaultConfiguration(): ChordProFormatterConfiguration {
    return { ...getBaseDefaultConfig(), ...chordProSpecificDefaults } as ChordProFormatterConfiguration;
  }

  /**
   * Formats a song into a ChordPro chord sheet.
   * @param {Song} song The song to be formatted
   * @returns {string} The ChordPro string
   */
  format(song: Song): string {
    const { lines } = song;
    const metadata = song.getMetadata(this.configuration);
    const { metadataLines, contentLines } = this.separateMetadataFromContent(lines);
    const formattedMetadataLines = this.formatMetadataSection(metadataLines, metadata);
    const formattedContentLines = this.formatContentSection(contentLines, metadata, song);
    return this.combineMetadataAndContent(formattedMetadataLines, formattedContentLines);
  }

  private separateMetadataFromContent(lines: Line[]): { metadataLines: Line[], contentLines: Line[] } {
    const metadataLines: Line[] = [];
    const contentLines: Line[] = [];
    let foundContentLine = false;

    lines.forEach((line) => {
      const isMetadataLine = line.items.length === 1 &&
        line.items[0] instanceof Tag &&
        (line.items[0] as Tag).isMetaTag();

      // Only treat as metadata if it appears before any content line
      // This preserves contextual directives like key changes within the song
      if (isMetadataLine && !foundContentLine) {
        metadataLines.push(line);
      } else {
        contentLines.push(line);
        if (line.hasRenderableItems()) {
          foundContentLine = true;
        }
      }
    });

    return { metadataLines, contentLines };
  }

  private formatMetadataSection(metadataLines: Line[], metadata: Metadata): string[] {
    return metadataLines.map((line) => {
      const tag = line.items[0] as Tag;

      if (!tag.isStandardOrCustomMetaTag()) {
        return `{meta: ${tag.originalName} ${this.formatTagValue(tag.value, metadata)}}`;
      }
      return this.formatTag(tag, metadata);
    });
  }

  private formatContentSection(contentLines: Line[], metadata: Metadata, song: Song): string {
    return contentLines
      .map((line) => this.formatLine(line, metadata, song))
      .join('\n');
  }

  formatLine(line: Line, metadata: Metadata, song: Song): string {
    return line.items
      .map((item) => this.formatItem(item, metadata, line, song))
      .join('');
  }

  formatItem(item: Item, metadata: Metadata, line: Line, song: Song): string {
    type constructor = any;
    type handlerFunc = any;

    const handlers = new Map<constructor, handlerFunc>([
      [Tag, (i: Item) => this.formatTag(i as Tag, metadata)],
      [ChordLyricsPair, (i: Item) => this.formatChordLyricsPair(i as ChordLyricsPair, line, song)],
      [Comment, (i: Item) => this.formatComment(i as Comment)],
      [SoftLineBreak, (_i: Item) => '\\ '],
    ]);

    const handler = handlers.get(item.constructor);

    if (handler) {
      return handler(item);
    }

    if ('evaluate' in item) {
      return this.formatOrEvaluateItem(item, metadata);
    }

    throw new Error(`Don't know how to format a ${item}`);
  }

  private combineMetadataAndContent(formattedMetadataLines: string[], formattedContentLines: string): string {
    if (formattedMetadataLines.length > 0) {
      if (formattedContentLines.trim().length > 0) {
        return `${formattedMetadataLines.join('\n')}\n${formattedContentLines}`;
      }
      return formattedMetadataLines.join('\n');
    }

    return formattedContentLines;
  }

  formatOrEvaluateItem(item: Evaluatable, metadata: Metadata): string {
    if (this.configuration.evaluate) {
      return item.evaluate(metadata, this.configuration.metadata.separator);
    }

    if (item instanceof Ternary) {
      return this.formatTernary(item);
    }

    if (item instanceof Literal) {
      return item.evaluate();
    }

    throw new Error(`Don't know how to format a ${item.constructor.name}`);
  }

  formatTernary(ternary: Ternary): string {
    const {
      variable,
      valueTest,
      trueExpression,
      falseExpression,
    } = ternary;

    return [
      '%{',
      variable || '',
      this.formatValueTest(valueTest),
      this.formatExpressionRange(trueExpression),
      this.formatExpressionRange(falseExpression),
      '}',
    ].join('');
  }

  formatValueTest(valueTest: string | null): string {
    if (!valueTest) {
      return '';
    }

    return `=${valueTest}`;
  }

  formatExpressionRange(expressionRange: Evaluatable[]): string {
    if (!expressionRange.length) {
      return '';
    }

    return `|${expressionRange.map((expression) => this.formatExpression(expression)).join('')}`;
  }

  formatExpression(expression: Evaluatable): string {
    if (expression instanceof Ternary) {
      return this.formatTernary(expression);
    }

    if (expression instanceof Literal) {
      return expression.string;
    }

    return '';
  }

  formatTag(tag: Tag, metadata: Metadata): string {
    if (tag.hasAttributes()) {
      return `{${tag.originalName}: ${this.formatTagAttributes(tag, metadata)}}`;
    }

    if (tag.hasValue()) {
      return `{${tag.originalName}: ${this.formatTagValue(tag.value, metadata)}}`;
    }

    return `{${tag.originalName}}`;
  }

  formatTagValue(value: string, metadata: Metadata): string {
    if (!this.configuration.evaluate) {
      return value;
    }

    const expression = parseMetaValue(value);
    return expression ? expression.evaluate(metadata, this.configuration.metadata.separator) : value;
  }

  formatTagAttributes(tag: Tag, metadata: Metadata) {
    const keys = Object.keys(tag.attributes);

    if (keys.length === 0) {
      return '';
    }

    return keys.map((key) => `${key}="${this.formatTagValue(tag.attributes[key], metadata)}"`).join(' ');
  }

  formatChordLyricsPair(chordLyricsPair: ChordLyricsPair, line: Line, song: Song): string {
    return [
      this.formatChordLyricsPairChords(chordLyricsPair, line, song),
      this.formatChordLyricsPairLyrics(chordLyricsPair),
    ].join('');
  }

  formatChordLyricsPairChords(chordLyricsPair: ChordLyricsPair, line: Line, song: Song): string {
    if (chordLyricsPair.chords) {
      const chordObj = chordLyricsPair.chord;
      if (!chordObj) {
        return `[${chordLyricsPair.chords}]`;
      }

      const contextKey = this.configuration.applyChordStyle ? Key.wrap(line.key || song.key) : null;

      const normalizedChord = this.configuration.normalizeChords ?
        chordObj.normalize(contextKey, { normalizeSuffix: this.configuration.normalizeChordSuffix }) :
        chordObj;

      const finalChord = this.configuration.applyChordStyle ?
        this.changeChordType(normalizedChord, contextKey, song) :
        normalizedChord;

      return `[${finalChord}]`;
    }

    if (chordLyricsPair.annotation) {
      return `[*${chordLyricsPair.annotation}]`;
    }

    return '';
  }

  private changeChordType(chord: Chord, contextKey: Key | null, song: Song): Chord {
    const style = song.metadata.getSingle(CHORD_STYLE) as NullableChordStyle;

    switch (style) {
      case SYMBOL:
        return chord.toChordSymbol(contextKey);
      case SOLFEGE:
        return chord.toChordSolfege(contextKey);
      case NUMERAL:
        return chord.toNumeral(contextKey);
      case NUMBER:
        return chord.toNumeric(contextKey);
      default:
        return chord;
    }
  }

  formatChordLyricsPairLyrics(chordLyricsPair: ChordLyricsPair): string {
    return chordLyricsPair.lyrics || '';
  }

  formatComment(comment: Comment): string {
    return `#${comment.content}`;
  }
}

export default ChordProFormatter;
